// Build the GPT prompt from the incoming signal
const body = $input.first().json.body ?? $input.first().json;

const {
  signal_id,
  question,
  service,
  location,
  industry,
  source,
  intent_score,
  buying_stage,
  urgency,
  org_id,
  run_id,
  callback_url,
} = body;

const prompt = `You are a world-class direct-response copywriter. Generate a complete funnel asset bundle for a local service business targeting this consumer intent signal.

Signal details:
- Question / Post: "${question}"
- Service: ${service ?? 'Not specified'}
- Location: ${location ?? 'Not specified'}
- Industry: ${industry ?? 'Local Business'}
- Buying Stage: ${buying_stage ?? 'Research'}
- Urgency: ${urgency ?? 'Medium'}
- Intent Score: ${intent_score ?? 50}/100
- Platform Found On: ${source ?? 'Online'}

Return ONLY this JSON object — no markdown, no explanation:
{
  "landing_page": "<compelling headline for a page targeting this exact intent>",
  "landing_page_subheadline": "<subheadline with social proof and urgency — 1-2 sentences>",
  "faq": "<3-4 FAQ Q&As as plain text, Q: / A: format>",
  "cta": "<strong call-to-action phrase (10 words max)>",
  "ai_script": "<phone setter script — 5-7 short lines, uses [Name]/[Clinic] placeholders>",
  "email_sequence": "<3-email follow-up sequence, one short descriptor per email with send day>",
  "blog_outline": "<blog title + 5-section outline with SEO angle>",
  "social_posts": "<3 posts: Instagram caption, Facebook post, Instagram Reel hook (label each)>",
  "video_script": "<Hook (0-3s) + Problem (3-15s) + Solution (15-35s) + CTA (35-45s)>",
  "schema_suggestion": "<JSON-LD schema markup as an escaped string>"
}`;

return [{
  json: {
    signal_id: signal_id ?? null,
    question,
    service: service ?? null,
    location: location ?? null,
    industry: industry ?? null,
    org_id,
    run_id,
    callback_url,
    prompt,
  }
}];

const crypto = require('crypto');

const gptItem = $input.first();
const raw = gptItem.json.choices?.[0]?.message?.content ?? '{}';

// Parse GPT output
let parsed = {};
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { landing_page: 'Parse error — ' + raw.slice(0, 80) };
}

// Pull context from earlier in the chain
const ctx = $('Build GPT Prompt').first().json;

const payload = {
  workflow_type: 'asset_generation',
  status: 'complete',
  org_id: ctx.org_id,
  run_id: ctx.run_id,
  generated_assets: [{
    signal_id: ctx.signal_id,
    intent_signal: ctx.question,
    service: ctx.service,
    location: ctx.location,
    industry: ctx.industry,
    business_name: null,
    ...parsed,
  }],
};

const payloadStr = JSON.stringify(payload);
const hmacSecret = $env.N8N_HMAC_SECRET;
const signature = crypto.createHmac('sha256', hmacSecret).update(payloadStr).digest('hex');

return [{
  json: {
    callback_url: ctx.callback_url,
    payload: payloadStr,
    signature,
  }
}];

// Build error callback payload
const ctx = $('Build GPT Prompt').first().json;
const crypto = require('crypto');

const payload = {
  workflow_type: 'asset_generation',
  status: 'failed',
  org_id: ctx.org_id,
  run_id: ctx.run_id,
  error_message: 'WF3 asset generation failed',
  generated_assets: [],
};
const payloadStr = JSON.stringify(payload);
const signature = crypto.createHmac('sha256', $env.N8N_HMAC_SECRET).update(payloadStr).digest('hex');

return [{ json: { callback_url: ctx.callback_url, payload: payloadStr, signature } }];
